module AdsChecklist
  # The standard checklists: what to gather and record to take an ad account live, in the order to
  # do it, one list per platform. Access comes first, since every later step needs it, then billing,
  # tracking (nothing should spend before conversions are measured), the campaigns, the launch and
  # what follows. `how` guides the person through a step and `example` shows what to record; both
  # are read from here, not stored. Keys are fixed once used (and start with the platform); order,
  # group, title and detail can change, and Account#apply_standard_checklist brings every account
  # up to date.
  module Account::Defaults
    GROUPS = [ "Access", "Billing", "Tracking", "Campaigns", "Launch", "After launch" ].freeze

    GOOGLE = [
      { key: "google:access:account", group: "Access", title: "Google Ads account",
        detail: "The account's customer ID, whose account it is, and our access to it.",
        how: "The customer ID is the 123-456-7890 at the top right of Google Ads. Ask the client to add our address under Admin › Access and security › Users as Admin, rather than sharing a login. No account yet? Create it in the client's name, so it stays theirs.",
        example: "123-456-7890, the client's account; we're Admin" },
      { key: "google:access:manager", group: "Access", title: "Linked to our manager account",
        detail: "The account sits under our manager (MCC) account, so the whole team can reach it and it shows in our reporting.",
        how: "In our manager account: Accounts › + › Link existing account › the customer ID. The client accepts the request in their account under Admin › Access and security › Managers.",
        example: "Linked to our MCC 987-654-3210, accepted 12 Oct" },
      { key: "google:access:analytics", group: "Access", title: "Google Analytics",
        detail: "The site's GA4 property and measurement ID, with us as an editor.",
        how: "Analytics › Admin › Property access management › Add: our address, as Editor. The measurement ID (G-…) is under Admin › Data streams.",
        example: "Property 412345678, G-ABC123XYZ, we're Editor" },
      { key: "google:access:tag_manager", group: "Access", title: "Google Tag Manager",
        detail: "The container the site's tags live in, with us able to publish.",
        how: "Tag Manager › Admin › User management › Add: our address, with Publish on the container. No container? Tags can go in the site's code instead; say where.",
        example: "GTM-ABC1234, we can Publish" },
      { key: "google:access:website", group: "Access", title: "The website",
        detail: "Who can put tags and change pages on the site the ads send people to.",
        how: "A login to the site's CMS, or the name of whoever runs it and how quickly they can make changes. Tracking can't start without one of them.",
        example: "WordPress admin login in the vault; web team: Sam at Acme Web" },
      { key: "google:access:merchant_center", group: "Access", title: "Merchant Center",
        detail: "For selling products: the Merchant Center account with the product feed, linked to Ads.",
        how: "merchants.google.com › Settings › People and access › Add: our address as Admin; then Settings › Apps and services › Google Ads › Link. Not selling products online? Mark it not applicable.",
        example: "Merchant Center 123456789, feed from Shopify, linked" },
      { key: "google:access:business_profile", group: "Access", title: "Google Business Profile linked",
        detail: "For a local business: the profile linked, so ads can show the address and calls.",
        how: "Google Ads › Assets › Location › link the Business Profile (the client accepts in Business Profile). Mark it not applicable for a business with no premises customers visit.",
        example: "Acme Plumbing, Grand Rapids; linked as a location asset" },

      { key: "google:billing:payment", group: "Billing", title: "Payment set up, in the client's name",
        detail: "Who pays Google, how (card, bank, monthly invoicing), and that it's the client's own payment method.",
        how: "Billing › Settings. The payment method and payments profile should be the client's, so spend never runs through us. Note who to call when a card fails.",
        example: "Client's Amex ending 1004; automatic payments; Jane gets the receipts" },
      { key: "google:billing:budget", group: "Billing", title: "Budget agreed",
        detail: "The monthly budget, how it's split, and who approved it.",
        how: "Agree it in writing before anything goes live, with what happens at the end of the month (pause, or carry on). Google can spend up to twice a daily budget on one day.",
        example: "$3,000 a month: Search $2,400, Performance Max $600; approved by Jane 10 Oct" },

      { key: "google:tracking:google_tag", group: "Tracking", title: "Google tag on every page",
        detail: "The Google tag (AW-…) loads on every page of the site, directly or through Tag Manager.",
        how: "Google Ads › Goals › Conversions › Settings shows the tag ID. Check it fires on a few pages with Tag Assistant (tagassistant.google.com).",
        example: "AW-123456789 through GTM-ABC1234; checked on 5 pages" },
      { key: "google:tracking:conversions", group: "Tracking", title: "Conversion actions",
        detail: "Every action that counts (form sent, call, purchase, booking): its name, whether it's primary, its value and how it's counted.",
        how: "Goals › Conversions › New conversion action. Make the ones you bid for primary and the rest secondary, give each a value if the client can put one on it, and count leads once per click.",
        example: "Contact form (primary, $50, one); Calls from ads (primary, 60s+); Brochure download (secondary)" },
      { key: "google:tracking:enhanced_conversions", group: "Tracking", title: "Enhanced conversions",
        detail: "The email or phone number from a conversion, hashed, sent with it so Google matches more of them.",
        how: "Goals › Conversions › Settings › Enhanced conversions: on, through the Google tag or Tag Manager. The form's email field has to be readable by the tag.",
        example: "On, through GTM, reading the form's email field; diagnostics healthy" },
      { key: "google:tracking:analytics_link", group: "Tracking", title: "Analytics linked, auto-tagging on",
        detail: "GA4 linked to Ads both ways, its key events imported if wanted, and auto-tagging on so every click carries its gclid.",
        how: "Ads › Tools › Data manager › Google Analytics › Link. Admin › Account settings › Auto-tagging: on. Import a key event only if it isn't already a conversion here, or it counts twice.",
        example: "Linked to 412345678; auto-tagging on; no events imported (tracked in Ads)" },
      { key: "google:tracking:consent_mode", group: "Tracking", title: "Consent",
        detail: "A cookie banner and Consent Mode, where the law asks for one (the EEA, the UK, and some US states).",
        how: "Where visitors come from the EEA or UK, Google needs Consent Mode v2 to use their data: a consent banner (Cookiebot, CookieYes, OneTrust…) that sends consent to the Google tag. Elsewhere, record the decision.",
        example: "CookieYes with Consent Mode v2 (advanced); or: US only, no banner needed" },
      { key: "google:tracking:calls", group: "Tracking", title: "Calls tracked",
        detail: "Calls from ads and from the site counted as conversions, for a business that takes calls.",
        how: "Add a call asset with call reporting on, and a Calls from website conversion (a Google forwarding number swapped on the site). Set the minimum length that counts as a real call.",
        example: "Call asset (616) 555-0100; website calls via forwarding number; 60 seconds counts" },
      { key: "google:tracking:offline", group: "Tracking", title: "Leads back from the CRM",
        detail: "For leads that close later: the gclid kept with each lead, and sales sent back to Google as offline conversions.",
        how: "Add a hidden gclid field to the forms and keep it in the CRM, then import closed sales (Goals › Uploads, or the CRM's own Google Ads link). Mark it not applicable where a form or call is the whole story.",
        example: "HubSpot keeps the gclid; deals won import nightly through HubSpot's link" },
      { key: "google:webhooks", group: "Tracking", title: "Lead form webhooks",
        detail: "Where leads from lead form assets go besides the Ads download: each webhook's address and the keys and values it's set up with.",
        how: "In the lead form asset › Lead delivery: the webhook URL and key. Add each here with the keys and values it needs. Keep secrets in the vault, not here: name where they are." },
      { key: "google:tracking:test", group: "Tracking", title: "Test conversion recorded",
        detail: "A real test of each primary conversion, seen in Google Ads.",
        how: "Send the form and make a call through the site yourself (with Tag Assistant open), then check Goals › Conversions a few hours later.",
        example: "Form and call tested 14 Oct; both showing as Recording" },

      { key: "google:campaigns:goals", group: "Campaigns", title: "Goals and targets",
        detail: "What the ads are for, how success is measured, and the cost per lead or return the client can live with.",
        how: "Ask what a customer is worth and how many leads they can handle. That gives the target cost per lead (or return on ad spend) to bid towards.",
        example: "Booked jobs; up to $60 a lead; 40 leads a month" },
      { key: "google:campaigns:locations", group: "Campaigns", title: "Locations, languages and schedule",
        detail: "Where and when the ads run, and in which languages.",
        how: "Target people in the area (Presence), not people interested in it, unless the client serves visitors. Match the schedule to when they can answer the phone.",
        example: "25 miles around Grand Rapids, Presence; English; Mon–Sat 7am–7pm" },
      { key: "google:campaigns:keywords", group: "Campaigns", title: "Keywords and negatives",
        detail: "The keywords to bid on, and the negative list of searches never to pay for.",
        how: "Keyword Planner for volumes and costs; group keywords by service. Start a shared negative list (jobs, free, DIY, competitors' names unless wanted).",
        example: "4 ad groups, 62 keywords; shared negatives: 85 terms" },
      { key: "google:campaigns:structure", group: "Campaigns", title: "Campaigns and bidding",
        detail: "Which campaigns, their types, budgets and bid strategies.",
        how: "Start simple: Search for intent, Performance Max only with conversions tracked and enough budget. Maximize conversions until there's data, then a target.",
        example: "Search – Services ($80/day, Maximize conversions); PMax – Brand ($20/day)" },
      { key: "google:campaigns:ads", group: "Campaigns", title: "Ads and assets, approved by the client",
        detail: "The headlines, descriptions and assets (sitelinks, callouts, images, logo), and the client's approval of the wording.",
        how: "Write responsive search ads with 10–15 headlines; add sitelinks, callouts, a structured snippet, images and the logo. Send the client the wording and record when they approved it.",
        example: "2 RSAs per ad group, 6 sitelinks, logo and 8 images; approved by Jane 11 Oct" },
      { key: "google:campaigns:landing_pages", group: "Campaigns", title: "Landing pages and tracking parameters",
        detail: "The pages each ad group sends people to, and any tracking template or UTM parameters.",
        how: "Each page should match its ads, load fast on a phone, and have the form or number above the fold. With auto-tagging on, UTMs are only needed for other tools.",
        example: "/drain-cleaning, /water-heaters; final URL suffix utm_source=google&utm_medium=cpc" },
      { key: "google:campaigns:audiences", group: "Campaigns", title: "Audiences",
        detail: "Remarketing lists, customer lists and the audience segments added to observe or target.",
        how: "Tools › Shared library › Audience manager: a site visitors list from the Google tag, and a customer list (Customer Match) if the client shares one and the account qualifies.",
        example: "All visitors 540 days; customers (CSV, 1,200, 64% matched) as exclusion" },

      { key: "google:launch:policy", group: "Launch", title: "Ads approved, advertiser verified",
        detail: "Every ad approved, nothing limited, and advertiser verification done if Google asked for it.",
        how: "Ads › the Status column; Policy manager for anything disapproved. Verification (Billing › Advertiser verification) can take days: start it early.",
        example: "All ads Eligible; advertiser verification complete 9 Oct" },
      { key: "google:launch:sign_off", group: "Launch", title: "Client sign-off to go live",
        detail: "The client's yes to launch: budget, targeting and ads as built.",
        how: "Send them a summary (budget, where, what, the ads) and record who approved it and when.",
        example: "Approved by Jane by email, 14 Oct" },
      { key: "google:launch:live", group: "Launch", title: "Campaigns live",
        detail: "The day the campaigns went on, and that they're spending.",
        how: "Enable the campaigns, then check the next day: impressions, clicks, spend near the daily budget, nothing stuck in Learning or Limited.",
        example: "Live 15 Oct; first day 1,240 impressions, $74 spent" },

      { key: "google:after:conversions", group: "After launch", title: "Conversions arriving",
        detail: "Real conversions showing in Google Ads, matching what the client sees come in.",
        how: "A week in, compare conversions in Ads with the leads the client actually got. A big gap means double counting or a tag that doesn't fire.",
        example: "9 conversions in Ads, client counted 10 leads (one phoned direct)" },
      { key: "google:after:search_terms", group: "After launch", title: "First search terms review",
        detail: "What people actually searched for, with wasted searches added as negatives.",
        how: "After the first week: Insights and reports › Search terms. Add irrelevant ones to the negative list, and good ones as keywords.",
        example: "Reviewed 22 Oct: 31 negatives added, 4 new keywords" },
      { key: "google:after:reporting", group: "After launch", title: "Reporting",
        detail: "What the client gets, how often, and who receives it.",
        how: "A Looker Studio dashboard or a scheduled report: spend, conversions, cost per conversion, against the targets agreed.",
        example: "Monthly Looker Studio report to Jane and Bob, first on 1 Nov" },
      { key: "google:after:alerts", group: "After launch", title: "Alerts",
        detail: "Who hears when something breaks: disapprovals, a failed payment, spend off pace, conversions stopping.",
        how: "Add our address to the account's notifications (Admin › Notification settings), and set automated rules or scripts for spend and zero-conversion days.",
        example: "ads@ourteam.com on all notifications; rule: email if no conversions in 3 days" }
    ].freeze

    META = [
      { key: "meta:access:business_portfolio", group: "Access", title: "Business portfolio",
        detail: "The client's business portfolio (Business Manager): its ID, and who owns it.",
        how: "business.facebook.com › Settings › Business info shows the ID. It should be the client's own, with at least two of their people as admins so it's never locked out.",
        example: "Acme Plumbing, 1234567890123456; admins Jane and Bob" },
      { key: "meta:access:partner", group: "Access", title: "Our business added as a partner",
        detail: "Our business portfolio given access to the client's assets as a partner, rather than our people added one by one.",
        how: "The client: Settings › Partners › Add › Give a partner access to your assets › our business ID; then share the ad account, Page, dataset (pixel) and any catalog. We assign them to our people.",
        example: "Partner since 12 Oct: ad account (Manage), Page, dataset, no catalog" },
      { key: "meta:access:ad_account", group: "Access", title: "Ad account",
        detail: "The ad account's ID, and its currency and time zone, which can't be changed later.",
        how: "Settings › Accounts › Ad accounts shows the ID (act_…), currency and time zone. Check both before spending anything: the wrong ones mean a new account.",
        example: "act_1234567890, USD, America/Detroit; we're Manage" },
      { key: "meta:access:page", group: "Access", title: "Facebook Page",
        detail: "The Page the ads run as, with us able to advertise and answer comments.",
        how: "Shared with our business as a partner (above), with Advertise and Content. Check the Page's name, picture and contact details are current: they show on every ad.",
        example: "Acme Plumbing (facebook.com/acmeplumbing), we have Advertise and Content" },
      { key: "meta:access:instagram", group: "Access", title: "Instagram account",
        detail: "The Instagram account connected, so ads show as the business there too.",
        how: "Settings › Accounts › Instagram accounts › Add, or connect it in the Page's settings. Without it, Instagram ads run as the Facebook Page.",
        example: "@acmeplumbing connected 12 Oct" },
      { key: "meta:access:website", group: "Access", title: "The website",
        detail: "Who can put the pixel and change pages on the site the ads send people to.",
        how: "A login to the site's CMS, or the name of whoever runs it and how quickly they can make changes. Tracking can't start without one of them.",
        example: "Shopify staff account; web team: Sam at Acme Web" },

      { key: "meta:billing:payment", group: "Billing", title: "Payment set up, in the client's name",
        detail: "Who pays Meta, how, and any account spending limit.",
        how: "Billing and payments › Payment settings. The payment method should be the client's own. An account spending limit is a useful backstop.",
        example: "Client's Visa ending 4242; spending limit $5,000" },
      { key: "meta:billing:budget", group: "Billing", title: "Budget agreed",
        detail: "The monthly budget, how it's split, and who approved it.",
        how: "Agree it in writing before anything goes live, with what happens at the end of the month.",
        example: "$2,000 a month: prospecting $1,400, retargeting $600; approved by Jane 10 Oct" },

      { key: "meta:tracking:domain", group: "Tracking", title: "Domain verified",
        detail: "The site's domain verified in the client's business portfolio.",
        how: "Settings › Brand safety and suitability › Domains › Add: verify with the meta tag on the home page, a DNS TXT record, or an uploaded file.",
        example: "example.com verified by DNS TXT, 12 Oct" },
      { key: "meta:tracking:pixel", group: "Tracking", title: "Meta Pixel on every page",
        detail: "The pixel (dataset) ID, loading on every page of the site.",
        how: "Events Manager › Data sources shows the dataset ID. Install it through the site's integration (Shopify, WordPress) or Tag Manager, and check it with the Meta Pixel Helper extension.",
        example: "Pixel 1234567890123456 through GTM; Pixel Helper shows PageView on 5 pages" },
      { key: "meta:tracking:events", group: "Tracking", title: "Conversion events",
        detail: "The standard events that count (Lead, Purchase, Schedule…), when each fires, and its value.",
        how: "Use Meta's standard events, not custom ones, so campaigns can optimise for them. Fire Lead on the thank-you, not on clicking the button.",
        example: "Lead on /thank-you ($50); Contact on tel: clicks; Purchase from Shopify with value" },
      { key: "meta:tracking:conversions_api", group: "Tracking", title: "Conversions API",
        detail: "Events sent from the server as well as the browser, so ad blockers and lost cookies don't hide them.",
        how: "Events Manager › the dataset › Settings › Conversions API: through the site's integration (Shopify, WordPress), a partner, or the Gateway. Send an event_id with both so they're counted once.",
        example: "Through Shopify's integration, deduplicated; Event Match Quality 7.8 for Purchase" },
      { key: "meta:tracking:consent", group: "Tracking", title: "Consent",
        detail: "A cookie banner that holds the pixel back until a visitor agrees, where the law asks for one (the EEA, the UK, some US states).",
        how: "The banner (Cookiebot, CookieYes, OneTrust…) should block the pixel until consent. Elsewhere, record the decision.",
        example: "CookieYes blocks the pixel until consent; or: US only, no banner needed" },
      { key: "meta:tracking:test", group: "Tracking", title: "Test events received",
        detail: "A real test of each conversion event, seen in Events Manager.",
        how: "Events Manager › the dataset › Test events: open the site from there, send the form, and watch each event arrive from browser and server.",
        example: "Lead tested 14 Oct: browser and server, deduplicated" },
      { key: "meta:webhooks", group: "Tracking", title: "Lead ads to the CRM",
        detail: "Where leads from instant forms go besides the Leads Center: each webhook's address and the keys and values it's set up with.",
        how: "Connect the CRM in Leads Center › CRM setup, or send leads through a webhook (Zapier, Make, the CRM's own). Add each here with the keys and values it needs. Keep secrets in the vault, not here: name where they are." },

      { key: "meta:campaigns:goals", group: "Campaigns", title: "Goals and targets",
        detail: "What the ads are for, how success is measured, and the cost per result the client can live with.",
        how: "Ask what a customer is worth and how many leads they can handle. That sets the objective and the cost per result to aim for.",
        example: "Leads for kitchen remodels; up to $40 a lead; 50 a month" },
      { key: "meta:campaigns:special_category", group: "Campaigns", title: "Special ad category",
        detail: "Whether the ads are about housing, employment, credit, or social issues, elections and politics, which Meta requires to be declared.",
        how: "Declared on each campaign. A declared category limits targeting (no age, gender or postcode targeting), and an undeclared one gets ads rejected. Social issues ads also need the advertiser authorised.",
        example: "None: home services; or: Housing, declared on every campaign" },
      { key: "meta:campaigns:audiences", group: "Campaigns", title: "Audiences",
        detail: "Who the ads reach: locations, custom audiences (site visitors, customers, people who engaged), lookalikes and exclusions.",
        how: "Audiences › Create: site visitors from the pixel, a customer list if the client shares one, Page and Instagram engagers. Exclude existing customers from prospecting.",
        example: "30 miles around Grand Rapids; visitors 180 days; customers (1,200) excluded" },
      { key: "meta:campaigns:structure", group: "Campaigns", title: "Campaigns, budgets and placements",
        detail: "Which campaigns, their objectives, budgets and placements.",
        how: "Fewer campaigns learn faster: one prospecting and one retargeting is plenty to start. Leads or Sales as the objective, Advantage+ placements unless a creative only suits some.",
        example: "Prospecting – Leads ($45/day, Advantage+); Retargeting – Leads ($20/day)" },
      { key: "meta:campaigns:creative", group: "Campaigns", title: "Creative and copy, approved by the client",
        detail: "The images and videos in each placement's size, the copy, and the client's approval.",
        how: "Square (1:1) and vertical (9:16) versions of each, three to five ads per ad set. Send the client the ads and record when they approved them.",
        example: "4 images, 2 videos, 1:1 and 9:16; 3 primary texts; approved by Jane 11 Oct" },
      { key: "meta:campaigns:lead_forms", group: "Campaigns", title: "Instant forms",
        detail: "For lead ads: the form's questions, its privacy policy link, and the thank-you screen.",
        how: "Higher intent asks one more question (budget, timeframe) and fewer, better leads come. The privacy policy link is required. Mark it not applicable when ads send people to the site.",
        example: "Higher intent; name, phone, email, zip, timeframe; privacy policy /privacy" },
      { key: "meta:campaigns:url_parameters", group: "Campaigns", title: "Links and URL parameters",
        detail: "The pages the ads send people to, and the UTM parameters that tell Analytics where visits came from.",
        how: "In each ad's URL parameters: utm_source={{site_source_name}}&utm_medium=paid_social&utm_campaign={{campaign.name}}.",
        example: "/kitchens; utm_source={{site_source_name}}&utm_medium=paid_social&utm_campaign={{campaign.name}}" },

      { key: "meta:launch:review", group: "Launch", title: "Ads approved",
        detail: "Every ad through review, and the ad account and Page free of restrictions.",
        how: "Ads Manager › the Delivery column; Account Quality for any restriction or rejection, with a request for review if Meta got it wrong.",
        example: "All ads Active; Account Quality: no issues" },
      { key: "meta:launch:sign_off", group: "Launch", title: "Client sign-off to go live",
        detail: "The client's yes to launch: budget, audiences and ads as built.",
        how: "Send them a summary (budget, who, the ads) and record who approved it and when.",
        example: "Approved by Jane by email, 14 Oct" },
      { key: "meta:launch:live", group: "Launch", title: "Campaigns live",
        detail: "The day the campaigns went on, and that they're delivering.",
        how: "Publish, then check the next day: delivery, spend, the first results, and nothing stuck in Learning limited.",
        example: "Live 15 Oct; first day 8,400 impressions, $63 spent, 2 leads" },

      { key: "meta:after:events", group: "After launch", title: "Events arriving",
        detail: "Real conversions showing in Meta, matching what the client sees come in, with a healthy Event Match Quality.",
        how: "A week in, compare results in Ads Manager with the leads or sales the client actually got, and check Event Match Quality in Events Manager (6 or more is good).",
        example: "11 leads in Meta, client counted 11; EMQ 7.4" },
      { key: "meta:after:first_review", group: "After launch", title: "First performance review",
        detail: "After the learning phase: what's working, frequency, and creative fatigue.",
        how: "Around 50 results per ad set ends learning. Look at cost per result by ad, turn off the weakest, and watch frequency: above 3 or so, people tire of the ads.",
        example: "Reviewed 29 Oct: 2 ads paused, frequency 1.8, new video briefed" },
      { key: "meta:after:reporting", group: "After launch", title: "Reporting",
        detail: "What the client gets, how often, and who receives it.",
        how: "A scheduled Ads Manager report or a dashboard: spend, results, cost per result, against the targets agreed.",
        example: "Monthly report to Jane and Bob, first on 1 Nov" },
      { key: "meta:after:alerts", group: "After launch", title: "Alerts",
        detail: "Who hears when something breaks: rejected ads, a failed payment, spend off pace, events stopping.",
        how: "Our people on the business portfolio's notifications, and automated rules in Ads Manager for spend and zero-result days. Events Manager emails when a dataset stops receiving events.",
        example: "ads@ourteam.com on notifications; rule: email if no leads in 3 days" }
    ].freeze

    BY_PLATFORM = { "google" => GOOGLE, "meta" => META }.freeze
    BY_KEY = (GOOGLE + META).index_by { it[:key] }.freeze

    def self.for(platform) = BY_PLATFORM.fetch(platform.to_s, [])
  end
end
